  export const runScreen = <S, R>(screen: Screen<S, R>, io: LineIO, prompt = DEFAULT_PROMPT): Promise<R | undefined> => {
    writeAll(io, screen.start.out);
    return step({ screen, io, prompt }, screen.start);
  };

  /** Lines are read through readline's async iterator: none is lost when stdin is piped, and EOF reads as undefined. */
  export const lineIO = (input: NodeJS.ReadableStream, output: NodeJS.WritableStream): LineIO => {
    const lines = createInterface({ input, terminal: false })[Symbol.asyncIterator]();
    return {
      write: text => {
        output.write(`${text}\n`);
      },
      ask: async prompt => {
        output.write(prompt);
        const next = await lines.next();
        return next.done === true ? undefined : next.value;
      },
    };
  };
Why not node:readline/promises `rl.question`: with piped (non-TTY) stdin it drops the
lines that arrive before the question is asked, and after EOF it rejects with
ERR_USE_AFTER_CLOSE instead of returning undefined — every scripted e2e test (W2-13a)
pipes stdin. Why the result turn's `out` IS written: a screen's last words (W2-10's quit
line, a summary) live in the result turn. `step` takes a Session object: four parameters
break max-params 3. No `let`/`for`: no-restricted-syntax.

